mapper.select:
WITH TMP_TRD_BOK_TABLE AS ( SELECT H1.FINPROD_ID FINPROD_ID, SUM( H1.TRADE_AMT ) TDY_PRIN_AMT FROM ( SELECT H.FINPROD_ID FINPROD_ID, CASE PS WHEN 'T06' THEN - 1 * TRADE_AMT WHEN 'T07' THEN - 1 * TRADE_AMT ELSE TRADE_AMT END AS TRADE_AMT FROM TRD_PRODUCT_DEAL H WHERE H.TRADE_DATE = TO_DATE(#{current date},'YYYY-MM-DD') ) H1 GROUP BY H1.FINPROD_ID UNION ALL SELECT L.FINPROD_ID FINPROD_ID, SUM( L.TDY_PRIN_AMT ) TDY_PRIN_AMT FROM BOK_POSITION_PRD L, ( SELECT L1.FINPROD_ID, max( L1.CDATE ) CDATE FROM BOK_POSITION_PRD L1 WHERE L1.CDATE <= TO_DATE(#{current date},'YYYY-MM-DD') GROUP BY L1.FINPROD_ID ) L11 WHERE L11.FINPROD_ID = L.FINPROD_ID AND L11.CDATE = L.CDATE GROUP BY L.FINPROD_ID ),
TMEP_FIN_CASH_CALC_RULE AS ( SELECT PP.CASH_ID, PP.EFF_DATE, PP.YIELD * 100 YIELD, PP.FINPROD_ID, PP.BRANCH, S.CASH_TYPE_2 FROM FIN_CASH_CALC_RULE PP, FIN_CASH_INFO S, ( SELECT P.CASH_ID, MAX( P.EFF_DATE ) EFF_DATE FROM FIN_CASH_CALC_RULE P, FIN_CASH_INFO Q WHERE P.CASH_ID = Q.CASH_ID AND P.EFF_DATE <= TO_DATE(#{queryDate},'YYYY-MM-DD') GROUP BY P.CASH_ID, P.BRANCH ) QQ WHERE PP.CASH_ID = QQ.CASH_ID AND PP.EFF_DATE = QQ.EFF_DATE AND S.CASH_ID = QQ.CASH_ID ) SELECT A.FINPROD_MARKET_ID, A.FINPROD_ABBR, A.FINPROD_NAME, B.PORTFOLIO_ID, C.PORTFOLIO_NAME, ( SELECT S.ITEM_VALUE FROM sys_datadict_list S WHERE S.DICT_CODE = 'DISPOSE_PATTERN' AND S.ITEM_CODE = D.DEAL_MODE ) DEAL_MODE, ( SELECT S.ITEM_VALUE FROM sys_datadict_list S WHERE S.DICT_CODE = 'SALE_DEPT' AND S.ITEM_CODE = E.SALE_DEPARTMENT ) AS SALE_DEPARTMENT, CASE A.FINPROD_TYPE2 WHEN 'F24' THEN ( SELECT ( SELECT S.ITEM_VALUE FROM sys_datadict_list S WHERE S.DICT_CODE = 'CLIENT_RANK' AND S.ITEM_CODE = F.CUSTOM_LEVEL ) || ',' || F.AMT_MIN || ',' || F.AMT_MAX || ',' || F.TERM_MIN || ',' || F.TERM_MAX FROM PRD_LAYER_PARAM F ) ELSE NULL END AS PRODUCT_TYPE, ( SELECT S.ITEM_VALUE FROM sys_datadict_list S WHERE S.DICT_CODE = 'CCY' AND S.ITEM_CODE = A.CCY ) AS CCY, CASE WHEN A.FINPROD_TYPE2 = 'F24' THEN ( SELECT SUM( G.TRADE_AMT ) TRADE_AMT FROM TRD_PRODUCT_DEAL G WHERE G.PS = 'C1' AND G.FINPROD_ID = A.FINPROD_ID AND G.FINPROD_TYPE2 = A.FINPROD_TYPE2 AND G.TRADE_DATE <= TO_DATE(#{queryDate},'YYYY-MM-DD') ) ELSE ( SELECT sum( H.TRADE_AMT ) TRADE_AMT FROM TRD_PRODUCT_DEAL H WHERE H.FINPROD_ID IN ( SELECT I.FINPROD_ID FROM FIN_PRODUCT I WHERE I.FINPROD_ID IN ( SELECT J.FINPROD_ID FROM FIN_PRODUCT J WHERE J.FINPROD_ID = A.FINPROD_ID OR J.P_FINPROD_ID = A.FINPROD_ID ) ) AND H.PS = 'C1' AND H.TRADE_DATE <= TO_DATE(#{queryDate},'YYYY-MM-DD') ) END AS TRADE_AMT, CASE WHEN E.IS_LAY = 'N' AND #{current date} != #{queryDate} THEN （ SELECT sum( L.TDY_PRIN_AMT ) TDY_PRIN_AMT FROM BOK_POSITION_PRD L WHERE L.CDATE = TO_DATE(#{queryDate},'YYYY-MM-DD') and L.FINPROD_ID = A.FINPROD_ID） WHEN E.IS_LAY = 'N' AND #{current date} = #{queryDate} THEN ( SELECT TMP_TRD_BOK_TABLE.TDY_PRIN_AMT FROM TMP_TRD_BOK_TABLE TMP_TRD_BOK_TABLE WHERE TMP_TRD_BOK_TABLE.FINPROD_ID = A.FINPROD_ID ) WHEN E.IS_LAY = 'Y' AND #{current date} != #{queryDate} THEN ( SELECT sum( K.TDY_PRIN_AMT ) FROM BOK_POSITION_PRD K WHERE K.FINPROD_ID IN ( SELECT AA.FINPROD_ID FROM FIN_PRODUCT AA WHERE AA.P_FINPROD_ID = A.FINPROD_ID ) AND K.CDATE = TO_DATE(#{queryDate},'YYYY-MM-DD') ) WHEN E.IS_LAY = 'Y' AND #{current date} = #{queryDate} THEN ( SELECT sum( TMP_TRD_BOK_TABLE2.TDY_PRIN_AMT ) FROM TMP_TRD_BOK_TABLE TMP_TRD_BOK_TABLE2 WHERE TMP_TRD_BOK_TABLE2.FINPROD_ID IN ( SELECT AAA.FINPROD_ID FROM FIN_PRODUCT AAA WHERE AAA.P_FINPROD_ID = A.FINPROD_ID ) ) ELSE 0 END AS TDY_PRIN_AMT, A.VDATE, A.MDATE, CASE WHEN A.PROFIT_TYPE = '02' THEN ( CASE WHEN D.DEAL_MODE = '04' THEN (SELECT TMEP_FIN_CASH_CALC_RULE.YIELD YIELD FROM FIN_TRADE_PRODUCT P, TMEP_FIN_CASH_CALC_RULE TMEP_FIN_CASH_CALC_RULE WHERE P.FINPROD_ID = TMEP_FIN_CASH_CALC_RULE.FINPROD_ID AND P.BRANCH = TMEP_FIN_CASH_CALC_RULE.BRANCH AND P.FINPROD_ID = A.FINPROD_ID AND TMEP_FIN_CASH_CALC_RULE.CASH_TYPE_2 = 'C02'） ELSE ( SELECT TMEP_FIN_CASH_CALC_RULE.YIELD FROM TMEP_FIN_CASH_CALC_RULE TMEP_FIN_CASH_CALC_RULE WHERE TMEP_FIN_CASH_CALC_RULE.FINPROD_ID = A.FINPROD_ID AND TMEP_FIN_CASH_CALC_RULE.CASH_TYPE_2 = 'C02' ) END ) ELSE ( SELECT O.VALUATION FROM FIN_PRODUCT_VALUATION O, ( SELECT M.FINPROD_ID, max( M.VAL_DATE ) VAL_DATE FROM FIN_PRODUCT_VALUATION M WHERE M.VAL_DATE <= TO_DATE(#{current date},'YYYY-MM-DD') GROUP BY M.FINPROD_ID ) MM WHERE O.FINPROD_ID = MM.FINPROD_ID AND O.FINPROD_ID = A.FINPROD_ID AND O.VAL_DATE = MM.VAL_DATE ) END AS VALUATION, ( SELECT TMEP_FIN_CASH_CALC_RULE.YIELD FROM TMEP_FIN_CASH_CALC_RULE TMEP_FIN_CASH_CALC_RULE WHERE TMEP_FIN_CASH_CALC_RULE.FINPROD_ID = A.FINPROD_ID AND TMEP_FIN_CASH_CALC_RULE.CASH_TYPE_2 = 'C05' ) CLIENTYIELD, ( SELECT TMEP_FIN_CASH_CALC_RULE.YIELD FROM TMEP_FIN_CASH_CALC_RULE TMEP_FIN_CASH_CALC_RULE WHERE TMEP_FIN_CASH_CALC_RULE.FINPROD_ID = A.FINPROD_ID AND TMEP_FIN_CASH_CALC_RULE.CASH_TYPE_2 = 'C06' ) SALEYIELD, ( SELECT TMEP_FIN_CASH_CALC_RULE.YIELD FROM TMEP_FIN_CASH_CALC_RULE TMEP_FIN_CASH_CALC_RULE WHERE TMEP_FIN_CASH_CALC_RULE.FINPROD_ID = A.FINPROD_ID AND TMEP_FIN_CASH_CALC_RULE.CASH_TYPE_2 = 'C04' ) MANAGERYIELD, ( SELECT TMEP_FIN_CASH_CALC_RULE.YIELD FROM TMEP_FIN_CASH_CALC_RULE TMEP_FIN_CASH_CALC_RULE WHERE TMEP_FIN_CASH_CALC_RULE.FINPROD_ID = A.FINPROD_ID AND TMEP_FIN_CASH_CALC_RULE.CASH_TYPE_2 = 'C10' ) OTHERYIELD, A.ISSUE_TYPE FROM FIN_PRODUCT A, PTL_MANAGE_OBJ B, PTL_PORTFOLIO C, PA_FIN_PRODUCT D, FIN_PRODUCT_ADD E WHERE A.FINPROD_ID = B.MANAGE_OBJ_ID AND B.PORTFOLIO_ID = C.PORTFOLIO_ID AND A.FINPROD_ID = D.FINPROD_ID AND A.FINPROD_ID = E.FINPROD_ID AND A.FINPROD_TYPE2 = 'F16'
AND C.PORTFOLIO_ID in
#{item}
AND D.DEAL_MODE = #{dealMode,jdbcType=VARCHAR}
AND E.SALE_DEPARTMENT = #{saleDepartment,jdbcType=VARCHAR}
AND A.VDATE >= TO_DATE(#{vdateStart},'YYYY-MM-DD')
AND A.VDATE <= TO_DATE(#{vdateEnd},'YYYY-MM-DD')
AND A.MDATE >= TO_DATE(#{mdateStart},'YYYY-MM-DD')
AND A.MDATE <= TO_DATE(#{mdateEnd},'YYYY-MM-DD')
AND A.FINPROD_ID in
#{item}
